#include <vector>
using namespace std;
class Solution {
public:
	int maxEuros(int n) {
		vector<vector<int>> dp(1008, vector<int>(1008, 0));
		for (int i = 1; i <= n; ++i) {
			dp[i][i] = i;
		}
		for (int i = 2; i <= n; ++i) {
			for (int j = i; j <= n; ++j) {
				dp[i][j] = dp[i][j - 1] + max(i - 1, 0);
				for (int k = 2; k <= i; ++k) {
					dp[i][j] = max(dp[i][j], dp[i - k][j - k] + (j < i ? i - 1 : i));
				}
			}
		}
		return dp[n][n];
	}
};
